using R8=std::array<std::array<Q,8>,8>;using V88=std::array<long,88>;
struct Index{Ambient &M;std::vector<V22>g,gw,reps;std::vector<int>rq;std::vector<std::unordered_map<long,std::vector<int>>>tabs;
 long keyraw(int q,Pair z){check(q>=1&&q<=12&&std::abs(z.a)<=32&&std::abs(z.b)<=16,"raw key range");return(q*65+z.a+32)*33+z.b+16;}
 Index(Ambient&m):M(m),g(m.vs.size()),gw(m.vs.size()){for(size_t k=0;k<m.vs.size();++k){for(int j=0;j<22;++j)for(int i=0;i<22;++i)g[k][j]+=m.vs[k][i]*m.G[i][j];for(int j=0;j<22;++j)for(int i=0;i<22;++i)gw[k][j]+=g[k][i]*m.W[i][j];}std::ifstream f("output/rank4_audit/M_shell12_orbit_reps.txt");int q;while(f>>q){V22 u{},a{},b{};for(long&x:u)f>>x;rq.push_back(q);reps.push_back(u);tabs.emplace_back();auto&t=tabs.back();for(int j=0;j<22;++j)for(int i=0;i<22;++i)a[j]+=u[i]*M.G[i][j];for(int j=0;j<22;++j)for(int i=0;i<22;++i)b[j]+=a[i]*M.W[i][j];for(size_t k=0;k<M.vs.size();++k){long s=0,v=0;for(int j=0;j<22;++j){s+=a[j]*M.vs[k][j];v+=b[j]*M.vs[k][j];}check((12*s-v)%23==0&&(2*v-s)%23==0,"index h integral");Pair z{(12*s-v)/23,(2*v-s)/23};t[keyraw(M.qn[k],z)].push_back(k+1);t[keyraw(M.qn[k],{-z.a,-z.b})].push_back(-int(k+1));}}
 }
 std::vector<int>const&list(int r,int q,Pair z){static const std::vector<int> empty;auto it=tabs[r].find(keyraw(q,z));return it==tabs[r].end()?empty:it->second;}
 V22 image(int s){auto v=M.vs[std::abs(s)-1];if(s<0)for(auto&x:v)x=-x;return v;}
 Pair ip(int i,int j){int sg=(i<0)^(j<0)?-1:1;--(i=std::abs(i));--(j=std::abs(j));long s=0,t=0;for(int k=0;k<22;++k){s+=g[i][k]*M.vs[j][k];t+=gw[i][k]*M.vs[j][k];}return{sg*(12*s-t)/23,sg*(2*t-s)/23};}
};
bool eq(Pair a,Pair b){return a.a==b.a&&a.b==b.b;}
struct Inverse{std::array<std::array<long,4>,4>P{},Qw{};long ell=1;R8 C{},R{};
 Inverse(std::array<V8,4>const&v){std::array<std::array<Q,16>,8>a{};for(int i=0;i<4;++i)for(int j=0;j<4;++j){C[i][j]=v[i][j];C[i][j+4]=-6*v[i][j+4];C[i+4][j]=v[i][j+4];C[i+4][j+4]=v[i][j]+v[i][j+4];}for(int i=0;i<8;++i)for(int j=0;j<8;++j){a[i][j]=C[i][j];a[i][j+8]=i==j;}for(int j=0;j<8;++j){int p=j;while(p<8&&a[p][j]==0)++p;check(p<8,"singular frame");std::swap(a[p],a[j]);Q z=a[j][j];for(int k=0;k<16;++k)a[j][k]/=z;for(int i=0;i<8;++i)if(i!=j){z=a[i][j];for(int k=0;k<16;++k)a[i][k]-=z*a[j][k];}}Z den=1;for(int i=0;i<8;++i)for(int j=0;j<8;++j){R[i][j]=a[i][j+8];den=lcm(den,R[i][j].get_den());}check(den.fits_slong_p(),"inverse denominator");ell=den.get_si();for(int i=0;i<4;++i)for(int j=0;j<4;++j){Q p=ell*R[i][j],q=ell*R[i+4][j];check(p.get_den()==1&&q.get_den()==1&&p.get_num().fits_slong_p()&&q.get_num().fits_slong_p(),"inverse coefficients");P[i][j]=p.get_num().get_si();Qw[i][j]=q.get_num().get_si();check(R[i][j+4]==-6*R[i+4][j]&&R[i+4][j+4]==R[i][j]+R[i+4][j],"inverse O linear");}for(int i=0;i<8;++i)for(int j=0;j<8;++j){Q z=0;for(int k=0;k<8;++k)z+=R[i][k]*C[k][j];check(z==(i==j),"inverse exact identity");}}
 bool integral(std::array<V22,4>const&u,M22 const&W){for(int i=0;i<4;++i)for(int k=0;k<22;++k){long s=0;for(int j=0;j<4;++j){s+=P[i][j]*u[j][k];for(int l=0;l<22;++l)s+=Qw[i][j]*W[k][l]*u[j][l];}if(s%ell)return false;}return true;}
 // Complete congruence signature; equality of signatures is exactly integrality.
 std::string residue(int j,V22 const&u,M22 const&W){std::string s;for(int i=0;i<4;++i)for(int k=0;k<22;++k){long z=P[i][j]*u[k];for(int l=0;l<22;++l)z+=Qw[i][j]*W[k][l]*u[l];z=(z%ell+ell)%ell;for(int b=0;b<8;++b)s.push_back(char((uint64_t(z)>>(b*8))&255));}return s;}
 std::string target(std::array<V22,4>const&u,M22 const&W){std::string s;for(int i=0;i<4;++i)for(int k=0;k<22;++k){long z=0;for(int j=0;j<3;++j){z+=P[i][j]*u[j][k];for(int l=0;l<22;++l)z+=Qw[i][j]*W[k][l]*u[j][l];}z=(-z%ell+ell)%ell;for(int b=0;b<8;++b)s.push_back(char((uint64_t(z)>>(b*8))&255));}return s;}
};
bool simple_frame=false;
std::array<int,4>choose(std::vector<SV>const&v,Ambient const&M){std::array<int,4>ix{};unsigned best=~0U;for(int i=0;i<(int)v.size();++i)for(int j=i+1;j<(int)v.size();++j){Pair z=h(v[i],v[j]);long d=long(v[i].q)*v[j].q-z.a*z.a-z.a*z.b-6*z.b*z.b;if(d<=0)continue;unsigned c=M.counts[key(v[i].q,v[j].q,z)];check(c>0,"absent pair passed");if(c<best){best=c;ix[0]=i;ix[1]=j;}}
 std::vector<V8>span={v[ix[0]].x,wmul(v[ix[0]].x),v[ix[1]].x,wmul(v[ix[1]].x)};for(int k=2;k<4;++k){unsigned long score=~0UL;int sel=-1;for(int i=0;i<(int)v.size();++i){auto st=span;st.push_back(v[i].x);st.push_back(wmul(v[i].x));if(rank(st)!=(int)span.size()+2)continue;if(simple_frame){sel=i;break;}unsigned long c=1;for(int j=0;j<k;++j){unsigned z=M.counts[key(v[ix[j]].q,v[i].q,h(v[ix[j]],v[i]))];check(z>0,"absent higher pair passed");if(c>100000000000000UL/z){c=100000000000000UL;break;}c*=z;}if(c<score){score=c;sel=i;}}check(sel>=0,"cannot find short frame");ix[k]=sel;span.push_back(v[sel].x);span.push_back(wmul(v[sel].x));}return ix;}
int main(int argc,char**argv){try{check(argc>=2,"usage independent_simultaneous flat_input [congruence]");bool early=argc>2&&std::string(argv[2])=="congruence";simple_frame=argc>2&&std::string(argv[2])=="simple";std::ofstream records(std::string(argv[1])+(early?".early_quads":".baseline_quads"));auto t0=Clock::now();Ambient M;M.table();Index idx(M);auto t1=Clock::now();std::cerr<<"index secs "<<std::chrono::duration<double>(t1-t0).count()<<'\n';std::ifstream f(argv[1]);long id;unsigned total=0;while(f>>id){H4 H;for(auto&r:H)for(auto&z:r)f>>z.a>>z.b;check(bool(f),"candidate input");M8 G=gram(H);Enum8 e(G);e.rec(7,Q(24),false);auto&v=e.vs;std::sort(v.begin(),v.end(),[](auto&a,auto&b){if(a.q!=b.q)return a.q<b.q;return a.x<b.x;});auto ix=choose(v,M);if(argc>3){std::ifstream ff(argv[3]);for(int j=0;j<4;++j){V8 wanted;for(long &x:wanted)ff>>x;check(bool(ff),"forced frame input");int found=-1;for(int k=0;k<(int)v.size();++k)if(v[k].x==wanted)found=k;check(found>=0,"forced vector not in source shell");ix[j]=found;}}std::array<V8,4>C;std::array<int,4>qn;std::array<std::array<Pair,4>,4>HH;for(int i=0;i<4;++i){C[i]=v[ix[i]].x;qn[i]=v[ix[i]].q;for(int j=0;j<4;++j)HH[i][j]=h(v[ix[i]],v[ix[j]]);}Inverse inv(C);unsigned long n2=0,n3=0,n4=0,integral=0,congruence_matches=0;std::array<V22,4>u{};
 for(int r=0;r<(int)idx.reps.size();++r)if(idx.rq[r]==qn[0]){u[0]=idx.reps[r];auto&a=idx.list(r,qn[1],HH[0][1]);auto&b=idx.list(r,qn[2],HH[0][2]);auto&c=idx.list(r,qn[3],HH[0][3]);std::unordered_map<std::string,std::vector<int>>res;if(early&&inv.ell>1)for(int k:c)res[inv.residue(3,idx.image(k),M.W)].push_back(k);
 for(int j:a){++n2;u[1]=idx.image(j);std::vector<int>secondc;if(!early||inv.ell==1)for(int l:c)if(eq(idx.ip(j,l),HH[1][3]))secondc.push_back(l);for(int k:b)if(eq(idx.ip(j,k),HH[1][2])){++n3;u[2]=idx.image(k);auto const*last=&secondc;std::vector<int>empty;if(early&&inv.ell>1){auto it=res.find(inv.target(u,M.W));last=it==res.end()?&empty:&it->second;}for(int l:*last){if(early&&inv.ell>1){++congruence_matches;if(!eq(idx.ip(j,l),HH[1][3]))continue;}if(!eq(idx.ip(k,l),HH[2][3]))continue;++n4;u[3]=idx.image(l);bool ok=inv.integral(u,M.W);if(early&&inv.ell>1)check(ok,"congruence signature mismatch");if(ok)++integral;records<<id<<' '<<r<<' '<<j<<' '<<k<<' '<<l<<' '<<ok<<'\n';}}}}
 std::cout<<"{\"id\":"<<id<<",\"frame\":[";for(int i=0;i<4;++i){if(i)std::cout<<',';vecout(C[i]);}std::cout<<"],\"inverseP\":[";for(int i=0;i<4;++i){if(i)std::cout<<',';std::cout<<'[';for(int j=0;j<4;++j){if(j)std::cout<<',';std::cout<<inv.P[i][j];}std::cout<<']';}std::cout<<"],\"inverseQ\":[";for(int i=0;i<4;++i){if(i)std::cout<<',';std::cout<<'[';for(int j=0;j<4;++j){if(j)std::cout<<',';std::cout<<inv.Qw[i][j];}std::cout<<']';}std::cout<<"],\"ell\":"<<inv.ell<<",\"pairs\":"<<n2<<",\"triples\":"<<n3<<",\"quadruples\":"<<n4<<",\"integral\":"<<integral<<",\"congruence_matches\":"<<congruence_matches<<",\"early_congruence\":"<<(early?"true":"false")<<"}\n";std::cout.flush();++total;if(total%100==0)std::cerr<<"done "<<total<<" seconds "<<std::chrono::duration<double>(Clock::now()-t1).count()<<'\n';}
 std::cerr<<"total "<<total<<" embedding seconds "<<std::chrono::duration<double>(Clock::now()-t1).count()<<" all seconds "<<std::chrono::duration<double>(Clock::now()-t0).count()<<'\n';return 0;}catch(std::exception const&e){std::cerr<<"ERROR "<<e.what()<<'\n';return 1;}}
